  scoped_refptr<VideoFrame> video_frame_b;

  scoped_refptr<DecoderBuffer> buffer = ReadTestDataFile(test_file_name);

  EXPECT_CALL(*demuxer_, Read(_))
      .WillOnce(ReturnBuffer(i_frame_buffer_))
