void Profiler::endFrame(const TypedValue *retval,
                        const char *symbol,
                        bool endMain) {
  if (m_stack) {
    // special case for main() frame that's only ended by endAllFrames()
    if (!endMain && m_stack->m_parent == nullptr) {
      return;
    }
    endFrameEx(retval, symbol);
    m_func_hash_counters[m_stack->m_hash_code]--;
    releaseFrame();
  }
}

bool operator()(const StringData* a, const StringData* b) const {
  return a == b || a->same(b);
}

bool isInteger() const {
  return m_str ? m_str->isInteger() : false;
}

String stringForEachFast(const String& str, Op action) {
  if (str.empty()) {
    return str;
  }

  return stringForEach<false>(str.size(), str, action);
}

explicit TraceProfiler(int flags)
  : Profiler(true)
  , m_traceBuffer(nullptr)
  , m_traceBufferSize(0)
  , m_nextTraceEntry(0)
  , m_traceBufferFilled(false)
  , m_maxTraceBuffer(0)
  , m_overflowCalls(0)
  , m_flags(flags)
{
  if (!(m_flags & IHaveInfiniteMemory) && pthread_mutex_trylock(&s_inUse)) {
    // This profiler uses a very large amount of memory. Only allow
    // one in the process at any time.
    m_successful = false;
  } else {
    m_maxTraceBuffer = RuntimeOption::ProfilerMaxTraceBuffer;
    Extension* ext = ExtensionRegistry::get(s_hotprofiler);
    assertx(ext);
    IniSetting::Bind(ext, IniSetting::PHP_INI_ALL,
                     "profiler.max_trace_buffer",
                     &m_maxTraceBuffer);
  }
}

php_image_filter_colorize(gdImagePtr im, int arg1 /* = 0 */, int arg2 /* = 0 */,
                          int arg3 /* = 0 */, int /*arg4*/ /* = 0 */) {
  int r = arg1;
  int g = arg2;
  int b = arg3;
  int a = arg1;
  return gdImageColor(im, r, g, b, a) == 1;
}

