bool ProfilerFactory::start(ProfilerKind kind,
                            long flags,
                            bool beginFrame /* = true */) {
  if (m_profiler != nullptr) {
    return false;
  }

  switch (kind) {
  case ProfilerKind::Hierarchical:
    m_profiler = req::make_raw<HierarchicalProfiler>(flags);
    break;
  case ProfilerKind::Sample:
    m_profiler = req::make_raw<SampleProfiler>();
    break;
  case ProfilerKind::Trace:
    m_profiler = req::make_raw<TraceProfiler>(flags);
    break;
  case ProfilerKind::Memo:
    m_profiler = req::make_raw<MemoProfiler>(flags);
    break;
  case ProfilerKind::External:
    if (g_system_profiler) {
      m_profiler = g_system_profiler->getHotProfiler();
    } else if (m_external_profiler) {
      m_profiler = m_external_profiler;
    } else {
      raise_invalid_argument_warning(
        "ProfilerFactory::setExternalProfiler() not yet called");
      return false;
    }
    break;
  default:
    raise_invalid_argument_warning("level: %d", static_cast<int>(kind));
    return false;
  }
  if (m_profiler && m_profiler->m_successful) {
    // This will be disabled automatically when the thread completes the request
    HPHP::EventHook::Enable();
    RequestInfo::s_requestInfo->m_profiler = m_profiler;
    if (beginFrame) {
      m_profiler->beginFrame("main()");
    }
    return true;
  }
  req::destroy_raw(m_profiler);
  m_profiler = nullptr;
  return false;
}

void popFrame(TraceIterator tIt, Stats& stats) {
  Frame callee = m_stack.back();
  m_stack.pop_back();
  Frame& caller = m_stack.back();
  char *cp = m_arcBuff;
  memcpy(cp, caller.trace->symbol, caller.len);
  cp += caller.len;
  if (caller.level >= 1) {
    std::pair<char*, int>& lvl = m_recursion[caller.level];
    memcpy(cp, lvl.first, lvl.second);
    cp += lvl.second;
  }
  memcpy(cp, HP_STACK_DELIM, HP_STACK_DELIM_LEN);
  cp += HP_STACK_DELIM_LEN;
  memcpy(cp, callee.trace->symbol, callee.len);
  cp += callee.len;
  if (callee.level >= 1) {
    std::pair<char*, int>& lvl = m_recursion[callee.level];
    memcpy(cp, lvl.first, lvl.second);
    cp += lvl.second;
  }
  *cp = 0;
  incStats(m_arcBuff, tIt, callee, stats);
}

static int exif_process_IFD_in_JPEG(image_info_type *ImageInfo,
                                    char *dir_start, char *offset_base,
                                    char *end,
                                    size_t IFDlength, size_t displacement,
                                    int section_index) {
  int de;
  int NumDirEntries;
  int NextDirOffset;

  ImageInfo->sections_found |= FOUND_IFD0;

  CHECK_BUFFER_R(dir_start, end, 2, 0);
  NumDirEntries = php_ifd_get16u(dir_start, ImageInfo->motorola_intel);

  if ((dir_start+2+NumDirEntries*12) > (offset_base+IFDlength)) {
    raise_warning("Illegal IFD size: x%04X + 2 + x%04X*12 = x%04X > x%04lX",
                    (int)((size_t)dir_start+2-(size_t)offset_base),
                    NumDirEntries,
                   (int)((size_t)dir_start+2+
                   NumDirEntries*12-(size_t)offset_base), IFDlength);
    return 0;
  }

  for (de=0;de<NumDirEntries;de++) {
    if (!exif_process_IFD_TAG(ImageInfo, dir_start + 2 + 12 * de,
                              offset_base, end, IFDlength, displacement,
                              section_index, 1,
                              exif_get_tag_table(section_index))) {
      return 0;
    }
  }
  /*
   * Ignore IFD2 if it purportedly exists
   */
  if (section_index == SECTION_THUMBNAIL) {
    return true;
  }
  /*
   * Hack to make it process IDF1 I hope
   * There are 2 IDFs, the second one holds the keys (0x0201 and 0x0202)
   * to the thumbnail
   */
  CHECK_BUFFER_R(dir_start+2+12*de, end, 4, 0);
  NextDirOffset =
    php_ifd_get32u(dir_start+2+12*de, ImageInfo->motorola_intel);
  if (NextDirOffset) {
    /* the next line seems false but here IFDlength means
       length of all IFDs */
    if (offset_base + NextDirOffset < offset_base ||
        offset_base + NextDirOffset > offset_base+IFDlength) {
      raise_warning("Illegal IFD offset");
      return 0;
    }
    /* That is the IFD for the first thumbnail */
    if (exif_process_IFD_in_JPEG(ImageInfo, offset_base + NextDirOffset,
                                 offset_base, end, IFDlength, displacement,
                                 SECTION_THUMBNAIL)) {
      if (ImageInfo->Thumbnail.filetype != IMAGE_FILETYPE_UNKNOWN &&
          ImageInfo->Thumbnail.size &&
          ImageInfo->Thumbnail.offset &&
          ImageInfo->read_thumbnail) {
        exif_thumbnail_extract(ImageInfo, offset_base, IFDlength);
      }
      return 1;
    } else {
      return 0;
    }
  }
  return 1;
}

Variant str_replace(const Variant& search, const Variant& replace,
                    const Variant& subject, int64_t& count, bool caseSensitive) {
  count = 0;
  if (subject.isArray()) {
    Array arr = subject.toArray();
    Array ret = Array::CreateDArray();
    int64_t c;
    for (ArrayIter iter(arr); iter; ++iter) {
      if (iter.second().isArray() || iter.second().is(KindOfObject)) {
        ret.set(iter.first(), iter.second());
        continue;
      }

      auto const replaced = str_replace(
        search, replace, iter.second().toString(), c, caseSensitive
      ).toString();
      ret.set(iter.first(), replaced);
      count += c;
    }
    return ret;
  }
  return str_replace(search, replace, subject.toString(), count,
                     caseSensitive);
}

  void *imCalloc(size_t nmemb, size_t size
#ifdef IM_MEMORY_CHECK
, int ln
#endif
  ) {
    assertx(m_mallocSize <= (size_t)RuntimeOption::ImageMemoryMaxBytes);
    size_t bytes = nmemb * size;
    if (bytes > (size_t)RuntimeOption::ImageMemoryMaxBytes ||
        m_mallocSize + bytes > (size_t)RuntimeOption::ImageMemoryMaxBytes) {
      return nullptr;
    }

#ifdef IM_MEMORY_CHECK
    void *ptr = local_malloc(sizeof(ln) + sizeof(size) + bytes);
    if (!ptr) return nullptr;
    memset(ptr, 0, sizeof(ln) + sizeof(size) + bytes);
    memcpy(ptr, &ln, sizeof(ln));
    memcpy((char*)ptr + sizeof(ln), &bytes, sizeof(bytes));
    m_mallocSize += bytes;
    m_alloced.insert(ptr);
    return ((char *)ptr + sizeof(ln) + sizeof(size));
#else
    void *ptr = local_malloc(sizeof(size) + bytes);
    if (!ptr) return nullptr;
    memcpy(ptr, &bytes, sizeof(bytes));
    memset((char *)ptr + sizeof(size), 0, bytes);
    m_mallocSize += bytes;
    return ((char *)ptr + sizeof(size));
#endif
  }

