                typename TTypes<T, 3>::Tensor input_backprop,
                typename TTypes<T>::Flat input_min_backprop,
                typename TTypes<T>::Flat input_max_backprop) {
  QuantizeAndDequantizePerChannelGradientImpl<CPUDevice, T>::Compute(
