  case NO_VALUE:
  case INT_VALUE:
  case REAL_VALUE:
  case STRING_VALUE:
  case TIME_VALUE:
  case LONG_DATA_VALUE:
  case DECIMAL_VALUE:
    break;
  }
  return false;
}

